import{_ as d,c as e,o as a,a8 as c}from"./chunks/framework.DBQiK-q5.js";const b=JSON.parse('{"title":"内置脚本语言","description":"","frontmatter":{"lang":"zh-cn","title":"内置脚本语言"},"headers":[],"relativePath":"advanced/script.md","filePath":"advanced/script.md","lastUpdated":1788999176000}'),o={name:"advanced/script.md"};function s(n,t,p,l,i,r){return a(),e("div",null,t[0]||(t[0]=[c(`<h1 id="内置脚本语言" tabindex="-1">内置脚本语言 <a class="header-anchor" href="#内置脚本语言" aria-label="Permalink to &quot;内置脚本语言&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本节内容</p><p>本节将介绍海豹内置的脚本语言，请善用侧边栏和搜索，按需阅读文档。</p></div><p>为了在很多地方支持实现一些逻辑，但又不至于直接使用学习门槛较高的正式编程语言，海豹提供了一种简单易学的脚本语言，可以称为「海豹语」「豹语」等。</p><h2 id="变量" tabindex="-1">变量 <a class="header-anchor" href="#变量" aria-label="Permalink to &quot;变量&quot;">​</a></h2><p>你可能注意到，在自定义文案等地方，出现了一些以 <code>$t</code> 开头的东西，这些是海豹中的<strong>变量</strong>。</p><p>变量的名称可以是汉字、字母和数字，<code>$t</code> 是一个特殊的变量前缀，还有其它的前缀。不同前缀代表不同的作用域：</p><table tabindex="0"><thead><tr><th>变量名字</th><th>用途</th><th>举例</th></tr></thead><tbody><tr><td>普通名字</td><td>玩家的角色属性</td><td>理智、力量、智力</td></tr><tr><td><code>$t开头</code></td><td>个人临时变量，不存数据库</td><td><code>$t随机点数</code></td></tr><tr><td><code>$m开头</code></td><td>个人变量，跨群存在</td><td><code>$m今日人品</code></td></tr><tr><td><code>$g开头</code></td><td>群变量，群内所有人共享</td><td><code>$g群主体重</code></td></tr></tbody></table><p>所有变量均可以在 <code>.rx</code> / <code>.rxh</code> / <code>.ra</code>/ <code>.text</code> 等指令以及「自定义文案」中使用。</p><div class="warning custom-block"><p class="custom-block-title">注意：<code>$t</code> 是临时变量</p><p><code>$t</code> 开头的临时变量的存活周期<strong>仅为单次指令执行</strong>，执行完毕后<strong>不应当认为该变量值还保留</strong>。</p><p>在下一次指令中使用上一次指令设置的 <code>$t</code> 变量属于<strong>未定义行为</strong>，可能会出现包括但不限于变量值不变，变量值丢失，变量值被覆盖，变量值变为随机数，变量值变成 <code>114514</code> 等任何情况。如果你需要这样的持久变量，请使用 <code>$m</code> 或 <code>$g</code> 代替。</p><p><em>内置的 <code>$t</code> 变量的值固定并不代表它们是持久变量，其值是在每次指令执行的初始阶段设置的。</em></p></div><div class="tip custom-block"><p class="custom-block-title">提示：变量不生效？</p><p>如果一部分变量无效，请检查海豹是否为最新版本。</p></div><div class="info custom-block"><p class="custom-block-title">内置变量与版本</p><p>下表依据 <code>sealdice-core</code> 的提交历史整理。版本列是<strong>首次包含该变量的正式发布标签</strong>；<code>rc</code> 和 <code>fix</code> 标签也按当时的发布版本记录。除非“适用范围”另有说明，变量在每次消息处理开始时初始化。当前代码中没有比 <code>v1.5.1</code> 更新、尚未打标签的全局内置变量。</p><p>示例结果以 QQ 群聊为例：玩家名和 QQ 昵称为“木落”，群组和个人骰子面数均为 100，当前规则模板为 <code>coc7</code>。日期、时间戳和人品值均为示例，实际结果会随运行时环境变化。</p><h3 id="用户与骰子" tabindex="-1">用户与骰子 <a class="header-anchor" href="#用户与骰子" aria-label="Permalink to &quot;用户与骰子&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量名</th><th>内容</th><th>适用范围</th><th>首次可用</th><th>后续调整</th><th>示例结果</th></tr></thead><tbody><tr><td><code>$t玩家</code></td><td>当前人物卡名；默认带尖括号，可由配置关闭</td><td>全部消息</td><td><code>v0.99.10</code></td><td>-</td><td><code>&lt;木落&gt;</code></td></tr><tr><td><code>$t玩家_RAW</code></td><td>当前人物卡名，不带尖括号</td><td>全部消息</td><td><code>v1.0.0-rc0</code></td><td>-</td><td><code>木落</code></td></tr><tr><td><code>$tQQ昵称</code></td><td>触发者昵称，带尖括号</td><td>全部消息</td><td><code>v0.99.10</code></td><td>-</td><td><code>&lt;木落&gt;</code></td></tr><tr><td><code>$t帐号昵称</code></td><td><code>$tQQ昵称</code> 的旧式写法</td><td>全部消息</td><td><code>v0.99.13</code></td><td>-</td><td><code>&lt;木落&gt;</code></td></tr><tr><td><code>$t账号昵称</code></td><td><code>$tQQ昵称</code> 的简体别名</td><td>全部消息</td><td><code>v1.1.0</code></td><td>-</td><td><code>&lt;木落&gt;</code></td></tr><tr><td><code>$t帐号ID</code></td><td>触发者的海豹格式 ID</td><td>全部消息</td><td><code>v0.99.14.fix2</code></td><td>-</td><td><code>QQ:123456789</code></td></tr><tr><td><code>$t账号ID</code></td><td><code>$t帐号ID</code> 的简体别名</td><td>全部消息</td><td><code>v1.1.0</code></td><td>-</td><td><code>QQ:123456789</code></td></tr><tr><td><code>$t帐号ID_RAW</code></td><td>触发者 ID 的原始部分</td><td>全部消息</td><td><code>v0.99.14.fix3</code></td><td>-</td><td><code>123456789</code></td></tr><tr><td><code>$t账号ID_RAW</code></td><td><code>$t帐号ID_RAW</code> 的简体别名</td><td>全部消息</td><td><code>v1.1.0</code></td><td>-</td><td><code>123456789</code></td></tr><tr><td><code>$tQQ</code></td><td>触发者的海豹格式 ID</td><td>全部消息</td><td><code>v0.99.10</code></td><td>历史兼容名称</td><td><code>QQ:123456789</code></td></tr><tr><td><code>$t骰子帐号</code></td><td>当前骰子账号的海豹格式 ID</td><td>全部消息</td><td><code>v0.99.10</code></td><td>-</td><td><code>QQ:123456789</code></td></tr><tr><td><code>$t骰子账号</code></td><td><code>$t骰子帐号</code> 的简体别名</td><td>全部消息</td><td><code>v1.1.0</code></td><td>-</td><td><code>QQ:123456789</code></td></tr><tr><td><code>$t骰子昵称</code></td><td>当前骰子的昵称</td><td>全部消息</td><td><code>v0.99.10</code></td><td>-</td><td><code>海豹核心</code></td></tr><tr><td><code>$t人品</code></td><td>当日人品值，范围为 1 到 100</td><td>全部消息</td><td><code>v0.99.10</code></td><td><code>v1.2.4</code> 起改为按日期、骰子账号和用户 ID 稳定计算</td><td><code>35</code></td></tr><tr><td><code>$t平台</code></td><td>当前平台名称</td><td>全部消息</td><td><code>v1.1.0</code></td><td><code>v1.5.0</code> 起 QQ 官方机器人固定为 <code>QQ-official</code></td><td><code>QQ</code></td></tr></tbody></table><h3 id="时间与群组" tabindex="-1">时间与群组 <a class="header-anchor" href="#时间与群组" aria-label="Permalink to &quot;时间与群组&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量名</th><th>内容</th><th>适用范围</th><th>首次可用</th><th>后续调整</th><th>示例结果</th></tr></thead><tbody><tr><td><code>$tDate</code></td><td>数字日期，格式 <code>YYYYMMDD</code></td><td>全部消息</td><td><code>v1.0.0-stable</code></td><td>-</td><td><code>20230109</code></td></tr><tr><td><code>$tYear</code></td><td>四位年份</td><td>全部消息</td><td><code>v1.0.0-stable</code></td><td>-</td><td><code>2023</code></td></tr><tr><td><code>$tMonth</code></td><td>月份</td><td>全部消息</td><td><code>v1.0.0-stable</code></td><td>-</td><td><code>1</code></td></tr><tr><td><code>$tDay</code></td><td>日期中的日</td><td>全部消息</td><td><code>v1.0.0-rc0</code></td><td>-</td><td><code>9</code></td></tr><tr><td><code>$tWeekday</code></td><td>星期，周一为 1、周日为 7</td><td>全部消息</td><td><code>v1.1.0</code></td><td><code>v1.1.1</code> 起周日从 0 调整为 7</td><td><code>1</code></td></tr><tr><td><code>$tHour</code></td><td>小时，24 小时制</td><td>全部消息</td><td><code>v1.0.0-stable</code></td><td>-</td><td><code>15</code></td></tr><tr><td><code>$tMinute</code></td><td>分钟</td><td>全部消息</td><td><code>v1.0.0-stable</code></td><td>-</td><td><code>41</code></td></tr><tr><td><code>$tSecond</code></td><td>秒</td><td>全部消息</td><td><code>v1.0.0-stable</code></td><td>-</td><td><code>55</code></td></tr><tr><td><code>$tTimestamp</code></td><td>10 位 Unix 时间戳</td><td>全部消息</td><td><code>v1.0.0-stable</code></td><td>-</td><td><code>1673250115</code></td></tr><tr><td><code>$t群名</code></td><td>当前群名称</td><td>群消息</td><td><code>v0.99.10</code></td><td>-</td><td><code>海豹核心·SealDice 用户群</code></td></tr><tr><td><code>$t群号</code></td><td>当前群的海豹格式 ID</td><td>群消息</td><td><code>v0.99.10</code></td><td>-</td><td><code>QQ-Group:987654321</code></td></tr><tr><td><code>$t群号_RAW</code></td><td>当前群 ID 的原始部分</td><td>群消息</td><td><code>v0.99.14.fix3</code></td><td>-</td><td><code>987654321</code></td></tr><tr><td><code>$t群组骰子面数</code></td><td>群组默认骰子面数</td><td>群消息</td><td><code>v0.99.10</code></td><td>-</td><td><code>100</code></td></tr><tr><td><code>$t个人骰子面数</code></td><td>触发者设置的个人骰子面数</td><td>全部消息</td><td><code>v0.99.10</code></td><td>-</td><td><code>100</code></td></tr><tr><td><code>$t当前骰子面数</code></td><td>本次掷骰实际采用的默认面数</td><td>群消息</td><td><code>v0.99.10</code></td><td>-</td><td><code>100</code></td></tr><tr><td><code>$t游戏模式</code></td><td>群当前规则模板名称，例如 <code>coc7</code></td><td>群消息</td><td><code>v1.1.0</code></td><td>-</td><td><code>coc7</code></td></tr><tr><td><code>$t规则模板</code></td><td><code>$t游戏模式</code> 的明确名称</td><td>群消息</td><td><code>v1.2.5</code></td><td>-</td><td><code>coc7</code></td></tr><tr><td><code>$tSystem</code></td><td><code>$t游戏模式</code> 的英文兼容名称</td><td>群消息</td><td><code>v1.2.5</code></td><td>-</td><td><code>coc7</code></td></tr><tr><td><code>$t当前记录</code></td><td>当前正在记录的日志名称；没有时为空字符串</td><td>群消息</td><td><code>v0.99.10</code></td><td>-</td><td><code>追书人</code></td></tr><tr><td><code>$t日志开启</code></td><td>日志是否开启，<code>0</code> 为关闭、<code>1</code> 为开启；私聊视为 <code>0</code></td><td>群消息</td><td><code>v1.5.0</code></td><td>-</td><td><code>0</code></td></tr><tr><td><code>$t权限等级</code></td><td>触发者的权限等级</td><td>群消息</td><td><code>v1.5.0</code></td><td>-</td><td><code>100</code></td></tr></tbody></table><h3 id="消息、自定义回复与常量" tabindex="-1">消息、自定义回复与常量 <a class="header-anchor" href="#消息、自定义回复与常量" aria-label="Permalink to &quot;消息、自定义回复与常量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量名</th><th>内容</th><th>适用范围</th><th>首次可用</th><th>后续调整</th><th>示例结果</th></tr></thead><tbody><tr><td><code>$t消息类型</code></td><td>消息位置：<code>group</code> 或 <code>private</code></td><td>全部消息</td><td><code>v1.1.1</code></td><td>-</td><td><code>group</code></td></tr><tr><td><code>$tMsgID</code></td><td>原始消息 ID</td><td>自定义回复</td><td><code>v0.99.14.fix3</code></td><td>-</td><td><code>-123</code></td></tr><tr><td><code>$t文本长度</code></td><td>触发消息的字节长度；汉字通常为 3，英文字母和数字为 1</td><td>自定义回复</td><td><code>v1.0.0-stable</code></td><td>-</td><td><code>6</code></td></tr><tr><td><code>$t轮数</code></td><td>带轮数执行时的执行轮数</td><td>指令与自定义文案上下文</td><td><code>v1.1.0</code></td><td>-</td><td><code>3</code></td></tr><tr><td><code>$t0</code></td><td>正则自定义回复匹配到的完整文本</td><td>正则自定义回复</td><td><code>v0.99.14.fix3</code></td><td>-</td><td><code>购买猫粮</code></td></tr><tr><td><code>$t1</code>、<code>$t2</code>、<code>...</code></td><td>正则自定义回复的第 1、2、... 个捕获组</td><td>正则自定义回复</td><td><code>v0.99.14.fix3</code></td><td>捕获组数量决定实际可用变量</td><td><code>猫粮</code></td></tr><tr><td><code>$t&lt;捕获组名&gt;</code></td><td>命名正则捕获组的匹配文本</td><td>正则自定义回复</td><td><code>v0.99.14.fix3</code></td><td>例如 <code>(?P&lt;A&gt;cc)</code> 对应 <code>$tA</code></td><td><code>cc</code></td></tr><tr><td><code>常量:APPNAME</code></td><td>软件名称</td><td>全部文案</td><td><code>v0.99.10</code></td><td>-</td><td><code>SealDice</code></td></tr><tr><td><code>常量:VERSION</code></td><td>当前软件版本号</td><td>全部文案</td><td><code>v0.99.10</code></td><td>随软件版本自动更新</td><td><code>1.4.0</code></td></tr><tr><td><code>&lt;分类&gt;:&lt;词条&gt;</code></td><td>任意自定义文案词条，例如 <code>娱乐:今日人品</code></td><td>对应文案上下文</td><td>随词条提供</td><td>由配置和扩展决定</td><td><code>&lt;木落&gt; 今日人品为35，人品还行吧</code></td></tr></tbody></table><p>具体指令或自定义文案还会在执行时额外写入结果变量，例如 <code>$t结果文本</code>、<code>$t判定值</code>、<code>$t表达式文本</code>。它们只对对应指令/词条有效，不是每次消息都存在；请以该文案编辑界面显示的变量标签和默认文案为准。</p></div><h2 id="数据类型和赋值" tabindex="-1">数据类型和赋值 <a class="header-anchor" href="#数据类型和赋值" aria-label="Permalink to &quot;数据类型和赋值&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 注意，目前并不支持写注释，此为教程中便于展示</span></span>
<span class="line"><span>// 文本类型</span></span>
<span class="line"><span>$t0 = &#39;文本&#39;</span></span>
<span class="line"><span>$t0 = &quot;也是文本&quot;</span></span>
<span class="line"><span>$t0 = \`特殊文本类型，可以插入表达式，例如，玩家的力量数值: {力量}\`</span></span>
<span class="line"><span>$t0 = \`另一种插入表达式的写法 {% 力量 %} \`</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 数字类型</span></span>
<span class="line"><span>$t0 = 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 布尔类型：没有专门的布尔类型，0 或空字符串被视为 False，非零和非空字符串为 True</span></span>
<span class="line"><span>$t0 &gt; 1</span></span>
<span class="line"><span>$t0 &gt;= 1</span></span>
<span class="line"><span>$t0 == 1</span></span>
<span class="line"><span>$t0 != 1</span></span>
<span class="line"><span>$t0 &lt; 1</span></span>
<span class="line"><span>$t0 &lt;= 1</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">注意：务必区分 <code>=</code> 与 <code>==</code></p><p>混淆 <code>=</code> 与 <code>==</code> 是小白常犯的错误之一。前者用于赋值而后者用于比较。当你试图在下文所述的条件算符或条件语句中，比较两个值时，需要使用 <code>==</code>。</p></div><h2 id="语句" tabindex="-1">语句 <a class="header-anchor" href="#语句" aria-label="Permalink to &quot;语句&quot;">​</a></h2><p>多个语句可以用 <code>;</code> 分隔，取分隔后的最后一项的值，为整个表达式的值，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$t0 = 1;2;3</span></span></code></pre></div><p>此时 <code>$t0</code> 的值为 3。</p><div class="warning custom-block"><p class="custom-block-title">注意：分号的使用</p><p><strong>不要</strong>在最后一条语句的后面再使用分号，会变得不幸。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 正确写法</span></span>
<span class="line"><span>if 1 {</span></span>
<span class="line"><span>    $t0 = 1;</span></span>
<span class="line"><span>    $t1 = 2 // [!code highlight]</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 错误写法</span></span>
<span class="line"><span>if 1 {</span></span>
<span class="line"><span>    $t0 = 1;</span></span>
<span class="line"><span>    $t1 = 2; // [!code error]</span></span>
<span class="line"><span>}</span></span></code></pre></div></div><h2 id="运算符" tabindex="-1">运算符 <a class="header-anchor" href="#运算符" aria-label="Permalink to &quot;运算符&quot;">​</a></h2><h3 id="数学运算" tabindex="-1">数学运算 <a class="header-anchor" href="#数学运算" aria-label="Permalink to &quot;数学运算&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>加减乘除余 + - * / %</span></span>
<span class="line"><span>乘方 ^ ** // 2 ** 3 或 2 ^ 3，即 2 的 3 次方</span></span></code></pre></div><h3 id="逻辑运算" tabindex="-1">逻辑运算 <a class="header-anchor" href="#逻辑运算" aria-label="Permalink to &quot;逻辑运算&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;&amp; 逻辑与</span></span>
<span class="line"><span>|| 逻辑或</span></span>
<span class="line"><span>!  逻辑非</span></span></code></pre></div><h3 id="骰子算符" tabindex="-1">骰子算符 <a class="header-anchor" href="#骰子算符" aria-label="Permalink to &quot;骰子算符&quot;">​</a></h3><p><code>d</code> 常规骰子算符，用法举例 <code>d20</code> <code>2d20k1</code> <code>d20 优势</code>。</p><p><code>f</code> 命运骰，随机骰 4 次，每骰结果可能是 -1 0 1，记为 - 0 +。</p><p><code>b</code> 奖励骰 (CoC)。</p><p><code>p</code> 惩罚骰 (CoC)。</p><p><code>c</code> 双十字。</p><h3 id="条件算符" tabindex="-1">条件算符 <a class="header-anchor" href="#条件算符" aria-label="Permalink to &quot;条件算符&quot;">​</a></h3><h4 id="条件算符-1" tabindex="-1">条件算符 <code>?</code> <a class="header-anchor" href="#条件算符-1" aria-label="Permalink to &quot;条件算符 \`?\`&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>灵视 &gt;= 40 ? &#39;如果灵视达到40以上，你就能看到这句话&#39;</span></span></code></pre></div><p>可以用这个指令测试，下同：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.st 灵视 41</span></span>
<span class="line"><span>.text {灵视 &gt;= 40 ? &#39;如果灵视达到 40 以上，你就能看到这句话&#39;}</span></span></code></pre></div><h4 id="多重条件算符" tabindex="-1">多重条件算符 <code>? ,</code> <a class="header-anchor" href="#多重条件算符" aria-label="Permalink to &quot;多重条件算符 \`? ,\`&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>灵视 &gt;= 80 ? &#39;看得很清楚吗？&#39;,</span></span>
<span class="line"><span>灵视 &gt;= 50 ? &#39;不错，再靠近一点……&#39;,</span></span>
<span class="line"><span>灵视 &gt;= 30 ? &#39;仔细听……&#39;,</span></span>
<span class="line"><span>灵视 &gt;= 0 ? &#39;呵，无知之人。&#39;</span></span></code></pre></div><p>应用举例，默认的 jrrp</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{$t玩家} 今日人品为{$t人品}，{%</span></span>
<span class="line"><span>    $t人品 &gt; 95 ? &#39;人品爆表！&#39;,</span></span>
<span class="line"><span>    $t人品 &gt; 80 ? &#39;运气还不错！&#39;,</span></span>
<span class="line"><span>    $t人品 &gt; 50 ? &#39;人品还行吧&#39;,</span></span>
<span class="line"><span>    $t人品 &gt; 10 ? &#39;今天不太行&#39;,</span></span>
<span class="line"><span>    1 ? &#39;流年不利啊！&#39;</span></span>
<span class="line"><span>%}</span></span></code></pre></div><h4 id="三目运算符" tabindex="-1">三目运算符 <code>? :</code> <a class="header-anchor" href="#三目运算符" aria-label="Permalink to &quot;三目运算符 \`? :\`&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>灵视 &gt;= 40 ? &#39;如果灵视达到 40 以上，你就能看到这句话&#39; : &#39;无知亦是幸运&#39;</span></span></code></pre></div><h2 id="条件语句" tabindex="-1">条件语句 <a class="header-anchor" href="#条件语句" aria-label="Permalink to &quot;条件语句&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if $t0 &gt; 10 {</span></span>
<span class="line"><span>    $t1 = &quot;aaa&quot;</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>    $t1 = &#39;bbb&#39;</span></span>
<span class="line"><span>}</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">提示：出现格式化错误</p><p>如果上面的代码输出「格式化错误」，那是因为你的 <code>$t0</code> 不是数值。字符串当然不能和数值比较大小，所以会报错。</p><p>解决方法：<code>.text {$t0=0}</code></p></div><p>实际测试：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.text {% if $t0 &gt; 10 { $t1=&quot;aaa&quot;} else { $t1 = &#39;bbb&#39; }; $t1 %}</span></span></code></pre></div>`,46)]))}const v=d(o,[["render",s]]);export{b as __pageData,v as default};
